/** Raised where Python's `float()` would raise ValueError. */
export class FloatConversionError extends Error {}

/**
 * `float(text)`
 * @param {string} text
 * @returns {number}
 */
export function pyFloat(text) {
  const value = String(text).replace(PY_STRIP_RE, '');

  const special = SPECIAL_RE.exec(value);
  if (special) {
    if (special[2].toLowerCase() === 'nan') return NaN;
    return special[1] === '-' ? -Infinity : Infinity;
  }

  if (!FLOAT_RE.test(value)) throw new FloatConversionError(String(text));
  return Number(value.replace(/_/g, ''));
}

/**
 * `str(value)` for a float.
 *
 * Both CPython and JS emit the shortest digit string that round-trips, so the
 * digits are taken from `toExponential()` and only the layout rules differ:
 * CPython switches to exponential notation when the decimal point sits at or
 * before -4, or past 16.
 */
export function pyFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const sign = negative ? '-' : '';
  if (value === 0) return `${sign}0.0`;

  const [mantissa, exponent] = Math.abs(value).toExponential().split('e');
  const digits = mantissa.replace('.', '');
  const pointPosition = parseInt(exponent, 10) + 1;

  if (pointPosition <= -4 || pointPosition > 16) {
    const head = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits[0];
    const power = pointPosition - 1;
    const suffix = String(Math.abs(power)).padStart(2, '0');
    return `${sign}${head}e${power < 0 ? '-' : '+'}${suffix}`;
  }
  if (pointPosition <= 0) {
    return `${sign}0.${'0'.repeat(-pointPosition)}${digits}`;
  }
  if (pointPosition >= digits.length) {
    return `${sign}${digits}${'0'.repeat(pointPosition - digits.length)}.0`;
  }
  return `${sign}${digits.slice(0, pointPosition)}.${digits.slice(pointPosition)}`;
}

