 * the `apply()` routine that renders a value through one.
 */

import {
  decimalAbs,
  decimalNormalize,
  decimalQuantize,
  decimalToFixedString,
} from '../core/decimal.mjs';
import {
  getCurrencySymbol,
  getDecimalSymbol,
  getGroupSymbol,
  getInfinitySymbol,
} from '../cldr/locale-en-us.mjs';

const NUMBER_CHARS = '#0,.@';

/** Minimum/maximum digit counts encoded by a pattern's integer or fraction part. */
function parsePrecision(part) {
  let min = 0;
  let max = 0;
  for (const char of part) {
    if (char === '@' || char === '0') {
      min += 1;
      max += 1;
    } else if (char === '#') {
      max += 1;
    } else if (char === ',' || char === '.') {
      continue;
    } else {
      break;
    }
  }
  return [min, max];
}

/** Primary/secondary group sizes, e.g. `#,##,##0` -> [3, 2]. */
function parseGrouping(part) {
  if (!part.includes(',')) return [1000, 1000];

  const pieces = part.split(',');
  const primary = pieces[pieces.length - 1].length;
  const secondary = pieces.length > 2 ? pieces[pieces.length - 2].length : primary;
  return [primary, secondary];
}

/** Split one pattern branch into prefix / number body / suffix. */
function splitBranch(branch) {
  let start = 0;
  while (start < branch.length && !NUMBER_CHARS.includes(branch[start])) start += 1;
  let end = branch.length;
  while (end > start && !NUMBER_CHARS.includes(branch[end - 1])) end -= 1;
  return [branch.slice(0, start), branch.slice(start, end), branch.slice(end)];
}

/**
 * Parse a CLDR number pattern.
 * @param {string} pattern e.g. `¤#,##0.00`
 */
export function parseNumberPattern(pattern) {
  const branches = pattern.split(';');
  const [positivePrefix, numberPattern, positiveSuffix] = splitBranch(branches[0]);

  let negativePrefix;
  let negativeSuffix;
  if (branches.length > 1) {
    const [prefix, , suffix] = splitBranch(branches[1]);
    negativePrefix = prefix;
    negativeSuffix = suffix;
  } else {
    negativePrefix = `-${positivePrefix}`;
    negativeSuffix = positiveSuffix;
  }

  const dot = numberPattern.indexOf('.');
  const integer = dot === -1 ? numberPattern : numberPattern.slice(0, dot);
  const fraction = dot === -1 ? '' : numberPattern.slice(dot + 1);

  return {
    pattern,
    numberPattern,
    prefix: [positivePrefix, negativePrefix],
    suffix: [positiveSuffix, negativeSuffix],
    grouping: parseGrouping(integer),
    intPrec: parsePrecision(integer),
    fracPrec: parsePrecision(fraction),
  };
