/** Babel's `_format_int`: left-pad to the minimum width, then group. */
function formatInt(pattern, value, min, locale, groupSeparator) {
  let head = value;
  if (head.length < min) head = '0'.repeat(min - head.length) + head;
  if (!groupSeparator) return head;

  const symbol = getGroupSymbol(locale);
  let size = pattern.grouping[0];
  let tail = '';
  while (head.length > size) {
    tail = symbol + head.slice(head.length - size) + tail;
    head = head.slice(0, head.length - size);
    size = pattern.grouping[1];
  }
  return head + tail;
