  if (value.isInfinite()) return getInfinitySymbol(locale);

  const rounded = decimalQuantize(value, -fracPrec[1]);
  const text = decimalToFixedString(rounded);
  const dot = text.indexOf('.');
  const intDigits = dot === -1 ? text : text.slice(0, dot);
  const fracDigits = dot === -1 ? '' : text.slice(dot + 1);

  return formatInt(pattern, intDigits, pattern.intPrec[0], locale, groupSeparator)
    + formatFrac(pattern, fracDigits || '0', locale, fracPrec);
}

/**
 * Babel's `NumberPattern.apply`.
 *
 * @param {object} pattern parsed pattern
 * @param {import('../core/decimal.mjs').Decimal} value
 * @param {object} locale
 * @param {{currency?: string, forceFrac?: [number, number], groupSeparator?: boolean}} options
 */
export function applyNumberPattern(pattern, value, locale, options = {}) {
  const { currency = null, forceFrac = null, groupSeparator = true } = options;

  const isNegative = value.isSigned() ? 1 : 0;
  const magnitude = decimalNormalize(decimalAbs(value));
  const fracPrec = forceFrac || pattern.fracPrec;

  const number = quantizeValue(pattern, magnitude, locale, fracPrec, groupSeparator);
  let result = pattern.prefix[isNegative] + number + pattern.suffix[isNegative];

  if (result.includes('¤') && currency !== null) {
    result = result.split('¤¤').join(currency.toUpperCase());
    result = result.split('¤').join(getCurrencySymbol(currency.toUpperCase(), locale));
  }
  return result;
}

