import { parseNumberPattern, applyNumberPattern } from './number-pattern.mjs';
import { EN_US, getCurrencyPrecision } from '../cldr/locale-en-us.mjs';

const patternCache = new Map();

function standardCurrencyPattern(locale) {
  let pattern = patternCache.get(locale.id);
  if (pattern === undefined) {
    pattern = parseNumberPattern(locale.currencyFormats.standard);
    patternCache.set(locale.id, pattern);
  }
  return pattern;
}

