/**
 * A minimal arbitrary-precision decimal, modelled on Python's `decimal.Decimal`.
 *
 * A finite value is stored as `(-1) ** sign * coefficient * 10 ** exponent`,
 * where the coefficient is kept as a plain digit string so that no numeric
 * type limits (and, per the project constraints, no BigInt) are involved.
 */

export const DEFAULT_PRECISION = 28;

/** Raised where Python's decimal module would signal InvalidOperation. */
export class InvalidOperation extends Error {
  constructor() {
    super('[<class \'decimal.InvalidOperation\'>]');
    this.name = 'InvalidOperation';
  }
}

export class Decimal {
  /**
   * @param {0|1} sign
   * @param {string} digits coefficient digits, no leading zeros (or a lone '0')
   * @param {number} exponent
   * @param {null|'inf'|'nan'} special
   */
  constructor(sign, digits, exponent, special = null) {
    this.sign = sign;
    this.digits = digits;
    this.exponent = exponent;
    this.special = special;
  }

  isSigned() {
    return this.sign === 1;
  }

  isInfinite() {
    return this.special === 'inf';
  }

  isNaN() {
    return this.special === 'nan';
  }

  isZero() {
    return this.special === null && this.digits === '0';
  }
}

const NUMERIC_RE = /^([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/;

/** Drop leading zeros, keeping at least one digit. */
function stripLeadingZeros(digits) {
  const trimmed = digits.replace(/^0+/, '');
  return trimmed === '' ? '0' : trimmed;
}

/** Number of significant digits, the way the decimal spec counts them. */
function coefficientLength(digits) {
  return stripLeadingZeros(digits).length;
}

/**
 * Build a Decimal from a numeric literal, as `Decimal(str)` does in Python.
 * Accepts the `inf` / `infinity` / `nan` spellings too.
 */
export function decimalFromString(text) {
  const value = String(text).trim();
  const special = /^([+-]?)(inf|infinity|nan)$/i.exec(value);
  if (special) {
    const sign = special[1] === '-' ? 1 : 0;
    const kind = special[2].toLowerCase() === 'nan' ? 'nan' : 'inf';
    return new Decimal(kind === 'nan' ? 0 : sign, '0', 0, kind);
  }

  const match = NUMERIC_RE.exec(value);
  if (!match || (match[2] === '' && (match[3] === undefined || match[3] === ''))) {
    throw new Error(`invalid decimal literal: ${text}`);
  }
  const sign = match[1] === '-' ? 1 : 0;
  const intPart = match[2];
  const fracPart = match[3] || '';
  const expPart = match[4] ? parseInt(match[4], 10) : 0;

  const digits = stripLeadingZeros(intPart + fracPart);
  const exponent = expPart - fracPart.length;
  return new Decimal(sign, digits, exponent);
}

/** `abs(value)` */
export function decimalAbs(value) {
  return new Decimal(0, value.digits, value.exponent, value.special);
}

/** `value.normalize()` — strip trailing zeros; zero collapses to exponent 0. */
export function decimalNormalize(value) {
  if (value.special !== null) return value;
  if (value.digits === '0') return new Decimal(value.sign, '0', 0);

  let digits = value.digits;
  let exponent = value.exponent;
  while (digits.length > 1 && digits.endsWith('0')) {
    digits = digits.slice(0, -1);
    exponent += 1;
  }
  return new Decimal(value.sign, digits, exponent);
}

/** Add one to a non-negative decimal digit string. */
function incrementDigits(digits) {
  const out = digits.split('');
  let i = out.length - 1;
  while (i >= 0) {
    if (out[i] === '9') {
      out[i] = '0';
      i -= 1;
    } else {
      out[i] = String(Number(out[i]) + 1);
      return out.join('');
    }
  }
  return `1${out.join('')}`;
}

/**
 * Decide a ROUND_HALF_EVEN tie-break for `kept` given the `dropped` tail.
 * @returns {boolean} true when the kept digits must be incremented
 */
function roundsUpHalfEven(kept, dropped) {
  const first = dropped.charCodeAt(0) - 48;
  if (first < 5) return false;
  if (first > 5) return true;
  if (/[1-9]/.test(dropped.slice(1))) return true;
  // Exact tie: round towards the even neighbour.
  return (kept.charCodeAt(kept.length - 1) - 48) % 2 === 1;
}

/**
 * `value.quantize(Decimal(1).scaleb(targetExponent))` with ROUND_HALF_EVEN,
 * raising InvalidOperation when the result would exceed `precision` digits.
 */
export function decimalQuantize(value, targetExponent, precision = DEFAULT_PRECISION) {
  if (value.isNaN()) return value;
  if (value.isInfinite()) throw new InvalidOperation();

  let digits;
  if (value.exponent >= targetExponent) {
    digits = value.digits + '0'.repeat(value.exponent - targetExponent);
  } else {
    const drop = targetExponent - value.exponent;
    // Left-pad so at least one digit survives the truncation.
    const padded = drop >= value.digits.length
      ? '0'.repeat(drop - value.digits.length + 1) + value.digits
      : value.digits;
    const kept = padded.slice(0, padded.length - drop);
    const dropped = padded.slice(padded.length - drop);
    digits = roundsUpHalfEven(kept, dropped) ? incrementDigits(kept) : kept;
  }

  if (coefficientLength(digits) > precision) throw new InvalidOperation();
  return new Decimal(value.sign, stripLeadingZeros(digits), targetExponent);
}

/** Render like Python's `f"{value:f}"` — plain notation, never exponential. */
export function decimalToFixedString(value) {
  if (value.isNaN()) return 'NaN';
  if (value.isInfinite()) return value.sign === 1 ? '-Infinity' : 'Infinity';

  const sign = value.sign === 1 ? '-' : '';
  if (value.exponent >= 0) {
    return sign + value.digits + '0'.repeat(value.exponent);
  }
  const fracLength = -value.exponent;
  const padded = value.digits.length <= fracLength
    ? '0'.repeat(fracLength - value.digits.length + 1) + value.digits
    : value.digits;
  const split = padded.length - fracLength;
  return `${sign}${padded.slice(0, split)}.${padded.slice(split)}`;
}

/** py-moneyed's `Currency` registry. */

import { CURRENCY_CODES } from '../cldr/currency-data.mjs';

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
    this.code = code;
  }
}

export class Currency {
  constructor(code) {
    this.code = code;
  }

  toString() {
    return this.code;
  }
}

export const CURRENCIES = Object.fromEntries(
  CURRENCY_CODES.map((code) => [code, new Currency(code)]),
);

/**
 * Look a currency up by code, case-insensitively.
 * @param {string} code
 * @returns {Currency}
 */
export function getCurrency(code) {
  const key = String(code).toUpperCase();
  if (!Object.prototype.hasOwnProperty.call(CURRENCIES, key)) {
    throw new CurrencyDoesNotExist(key);
  }
  return CURRENCIES[key];
}

