/**
 * Port of dataset/moneyed/test10.py
 *
 *   parser.add_argument('--amount', type=float, required=True)
 *   parser.add_argument('--currency', type=str, required=True)
 *   print(str(Money(args.amount, args.currency)))
 */

import path from 'node:path';
import process from 'node:process';

import { ArgumentParser, ArgumentParserExit } from './lib/cli/argparse.mjs';
import { pyFloat } from './lib/cli/py-float.mjs';
import { Money } from './lib/moneyed/index.mjs';
import { CurrencyDoesNotExist } from './lib/moneyed/currency.mjs';
import { InvalidOperation } from './lib/core/decimal.mjs';

/** Stands in for argparse's `type=float`. */
const float = (text) => pyFloat(text);
float.typeName = 'float';

/** Stands in for argparse's `type=str`. */
const str = (text) => String(text);
str.typeName = 'str';

function main(argv) {
  const parser = new ArgumentParser({ prog: path.basename(argv[1] ?? 'test10.mjs') });
  parser.addArgument(['--amount'], { type: float, required: true });
  parser.addArgument(['--currency'], { type: str, required: true });
  const args = parser.parseArgs(argv.slice(2));

  // 创建Money对象
  const m = new Money(args.amount, args.currency);
  // 打印字符串表示
  console.log(String(m));
}

try {
  main(process.argv);
  process.exitCode = 0;
} catch (error) {
  if (error instanceof ArgumentParserExit) {
    process.exitCode = error.status;
  } else if (error instanceof CurrencyDoesNotExist || error instanceof InvalidOperation) {
    // Same class of failure the reference exits 1 on (an uncaught exception).
    process.stderr.write(`${error.pyQualname}: ${error.message}\n`);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

