/**
 * A focused port of Python's `argparse` — enough of `ArgumentParser` to match
 * the reference CLI exactly: long-option abbreviation, `--opt=value`, the
 * negative-number heuristic, `-h/--help`, required-argument and
 * unrecognized-argument diagnostics, and the exit codes that go with them.
 */

// argparse's own heuristic for telling `-5` apart from an option string.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** Python's `repr()` for a str, used verbatim in type-conversion messages. */
export function pyReprString(value) {
  let body = String(value)
    .replace(/\\/g, '\\\\')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  if (body.includes("'") && !body.includes('"')) return `"${body}"`;
  return `'${body.replace(/'/g, "\\'")}'`;
}

/** Signals `parser.error()`; carries the process exit status. */
export class ArgumentParserExit extends Error {
  constructor(status, message) {
    super(message ?? `exit ${status}`);
    this.name = 'ArgumentParserExit';
    this.status = status;
  }
}

class Action {
  constructor({ optionStrings, dest, nargs, type, required, help, metavar }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
  }

  /** argparse's `_get_action_name`. */
  get name() {
    if (this.optionStrings.length > 0) return this.optionStrings.join('/');
    return this.metavar ?? this.dest;
  }

  /** argparse's `_format_action_invocation`. */
  get invocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    const args = this.metavar ?? this.dest.toUpperCase();
    return this.optionStrings.map((option) => `${option} ${args}`).join(', ');
  }
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean, stdout?: (s: string) => void,
   *          stderr?: (s: string) => void}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? 'prog';
    this.stdout = options.stdout ?? ((text) => process.stdout.write(text));
    this.stderr = options.stderr ?? ((text) => process.stderr.write(text));
    this.actions = [];
    this.optionStringActions = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        isHelp: true,
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * @param {string[]} flags option strings, e.g. `['--amount']`
   * @param {{type?: Function, required?: boolean, nargs?: number,
   *          help?: string, metavar?: string, dest?: string,
   *          isHelp?: boolean}} [config]
   */
  addArgument(flags, config = {}) {
    const dest = config.dest ?? flags
      .find((flag) => flag.startsWith('--'))
      ?.replace(/^--/, '')
      .replace(/-/g, '_')
      ?? flags[0].replace(/^-/, '');

    const action = new Action({
      optionStrings: flags,
      dest,
      nargs: config.nargs ?? 1,
      type: config.type ?? String,
      required: config.required ?? false,
      help: config.help,
      metavar: config.metavar,
    });
    action.isHelp = config.isHelp === true;

    this.actions.push(action);
    for (const flag of flags) this.optionStringActions.set(flag, action);
    return action;
  }

  get hasNegativeNumberOptionals() {
    return this.actions.some((action) => action.optionStrings
      .some((option) => NEGATIVE_NUMBER_RE.test(option)));
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const option = action.optionStrings[0];
      const body = action.nargs === 0
        ? option
        : `${option} ${action.metavar ?? action.dest.toUpperCase()}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const indent = 2;
    const maxLength = Math.max(
      0,
      ...this.actions.map((action) => action.invocation.length + indent),
    );
    const helpPosition = Math.min(maxLength + 2, 24);
    const actionWidth = helpPosition - indent - 2;

    const lines = [this.formatUsage(), '\noptions:\n'];
    for (const action of this.actions) {
      const header = action.invocation;
      if (!action.help) {
        lines.push(`${' '.repeat(indent)}${header}\n`);
      } else if (header.length <= actionWidth) {
        lines.push(`${' '.repeat(indent)}${header.padEnd(actionWidth)}  ${action.help}\n`);
      } else {
        lines.push(`${' '.repeat(indent)}${header}\n${' '.repeat(helpPosition)}${action.help}\n`);
      }
    }
    return `${lines.join('').replace(/\n+$/, '')}\n`;
  }

  printHelp() {
    this.stdout(this.formatHelp());
  }

  /** Write usage plus `prog: error: message` to stderr and exit 2. */
  error(message) {
    this.stderr(this.formatUsage());
    this.stderr(`${this.prog}: error: ${message}\n`);
    throw new ArgumentParserExit(2, message);
  }

  /** All option strings whose long form starts with `prefix`. */
  #optionTuples(argString) {
    const equals = argString.indexOf('=');
    const prefix = equals === -1 ? argString : argString.slice(0, equals);
    const explicitArg = equals === -1 ? null : argString.slice(equals + 1);

    const tuples = [];
    if (argString.startsWith('--')) {
      for (const [option, action] of this.optionStringActions) {
        if (option.startsWith(prefix)) tuples.push({ action, optionString: option, explicitArg });
      }
    } else {
      // Single-dash form: exact prefix, or `-xVALUE`.
      for (const [option, action] of this.optionStringActions) {
        if (option === prefix) {
          tuples.push({ action, optionString: option, explicitArg });
        } else if (option.startsWith(argString)) {
          tuples.push({ action, optionString: option, explicitArg: null });
        }
      }
    }
    return tuples;
  }

  /**
   * argparse's `_parse_optional`.
   * @returns {null|{action: Action|null, optionString: string, explicitArg: string|null}}
   *   `null` means "this is not an option string".
   */
  #parseOptional(argString) {
    if (!argString.startsWith('-')) return null;
    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    if (argString.includes('=')) {
      const index = argString.indexOf('=');
      const optionString = argString.slice(0, index);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          explicitArg: argString.slice(index + 1),
        };
      }
    }

    const tuples = this.#optionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER_RE.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  #convert(action, raw) {
    try {
      return action.type(raw);
    } catch {
      const typeName = action.type.typeName ?? action.type.name;
      this.error(`argument ${action.name}: invalid ${typeName} value: ${pyReprString(raw)}`);
      return undefined;
    }
  }

  /**
   * @param {string[]} argv arguments after the program name
   * @returns {{[key: string]: unknown}}
   */
  parseArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = undefined;
    }

    const extras = [];
    const seen = new Set();
    let index = 0;

    while (index < argv.length) {
      const arg = argv[index];
      if (arg === '--') {
        extras.push(...argv.slice(index + 1));
        break;
      }

      const option = this.#parseOptional(arg);
      if (option === null || option.action === null) {
        extras.push(arg);
        index += 1;
        continue;
      }

      const { action } = option;
      index += 1;

      if (action.isHelp) {
        this.printHelp();
        throw new ArgumentParserExit(0);
      }

      let raw;
      if (option.explicitArg !== null) {
        raw = option.explicitArg;
      } else if (index < argv.length && this.#parseOptional(argv[index]) === null) {
        raw = argv[index];
        index += 1;
      } else {
        this.error(`argument ${action.name}: expected one argument`);
      }

      namespace[action.dest] = this.#convert(action, raw);
      seen.add(action);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

